    ".alignpageind": { syntax: ".alignpageind <target>[, <interval>[, <fill>[, <offset>]]]", description: "Alignment of a page block indirectly.\n\nUsing .alignblk in the middle of executable code is usually problematic as the alignment is done there as well. This directive can do the alignment padding outside of the execution flow." },
